<div class="admin-panel service-list"><div class="panel-heading"><h2>Services List <span class="service-count-badge"><?= $total ?></span></h2><a class="service-category-link" href="index.php?page=admin&amp;section=services-category-add">+ Add Category</a></div><div class="table-responsive"><table class="table admin-table"><thead><tr><th>#</th><th>Service Code</th><th>Service Name</th><th>Category</th><th>Description</th><th>Price (Rs.)</th><th>Duration (Min)</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="9" class="empty-table">No services found.</td></tr><?php else: foreach($rows as $n=>$row): ?><tr><td><?= (($filters['page']-1)*$filters['per_page'])+$n+1 ?></td><td><strong><?= e($row['service_code']) ?></strong></td><td><?= e($row['service_name']) ?></td><td><?= e($row['category_name']?:'-') ?></td><td><?= e($row['description']?:'-') ?></td><td><?= number_format((float)$row['price'],2) ?></td><td><?= $row['duration_minutes']!==null?(int)$row['duration_minutes']:'-' ?></td><td><span class="service-status service-status-<?= e($row['status']) ?>"><?= e(ucfirst($row['status'])) ?></span></td><td><div class="service-actions"><a class="btn btn-light btn-sm" href="index.php?page=admin&amp;section=services-view&amp;id=<?= (int)$row['id'] ?>">View</a><a class="btn btn-primary btn-sm" href="index.php?page=admin&amp;section=services-edit&amp;id=<?= (int)$row['id'] ?>">Edit</a><form method="post" action="index.php?page=admin&amp;section=services-delete" onsubmit="return confirm('Remove this service?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="service_id" value="<?= (int)$row['id'] ?>"><button class="btn btn-danger btn-sm" type="submit">Remove</button></form></div></td></tr><?php endforeach; endif; ?></tbody></table></div><div class="service-pagination"><span>Showing <?= $total?((($filters['page']-1)*$filters['per_page'])+1):0 ?> to <?= min($filters['page']*$filters['per_page'],$total) ?> of <?= $total ?> services</span><div><?php for($p=1;$p<=$pages;$p++): ?><a class="<?= $p===$filters['page']?'active':'' ?>" href="?page=admin&amp;section=services&amp;search=<?= urlencode($filters['search']) ?>&amp;category_id=<?= $filters['category_id'] ?>&amp;status=<?= urlencode($filters['status']) ?>&amp;page_no=<?= $p ?>&amp;per_page=<?= $filters['per_page'] ?>"><?= $p ?></a><?php endfor; ?></div></div></div>
